import Foundation

/// Distinguishes a newly opened front window from focus generated by our own AX writes.
package struct NativeFocusObservation {
    package static let suppressionInterval = 0.45
    package private(set) var focusedID: String?
    private var admissionDeadlines: [String: Double] = [:]
    private var raisedUntil: [String: Double] = [:]
    private var suppressedFocus: String?
    private struct PointerPress {
        let screen: String
        let at: Double
        let nearEdge: Bool
        var until: Double
        var releaseScreen: String?

        func allows(_ owner: String?) -> Bool {
            guard let owner else { return true }
            return screen == owner && (releaseScreen == nil || releaseScreen == owner)
        }
    }
    private var pointerPress: PointerPress?
    package var scopesPointerFocus: Bool {
        guard let press = pointerPress else { return false }
        return press.nearEdge || (press.releaseScreen != nil && press.releaseScreen != press.screen)
    }
    private var bodyClick: (target: String, at: Double, until: Double)?
    package func inputBaseline(at time: Double, lastManagerFocus: Double) -> Double {
        if let click = bodyClick, time < click.until { return click.at }
        if let press = pointerPress, time < press.until { return press.at }
        return max(lastManagerFocus, pointerPress?.at ?? 0)
    }

    package init() {}

    package mutating func discovered(_ id: String, at time: Double) {
        admissionDeadlines[id] = time + 0.35
    }

    package var nextAdmission: Double? { admissionDeadlines.values.min() }

    package func awaitingFocus(_ id: String) -> Bool { admissionDeadlines[id] != nil }

    package mutating func admitBackground(at time: Double) -> Bool {
        let count = admissionDeadlines.count
        admissionDeadlines = admissionDeadlines.filter { $0.value > time }
        return admissionDeadlines.count != count
    }

    package mutating func raise(_ id: String, activate: Bool, at time: Double) -> Bool {
        guard activate || !awaitingFocus(id) else { return false }
        if activate {
            supersedeBodyClick(with: id)
            if bodyClick != nil { bodyClick?.until = time + Self.suppressionInterval }
        }
        admissionDeadlines.removeValue(forKey: id)
        raisedUntil = raisedUntil.filter { $0.value > time }
        raisedUntil[id] = time + Self.suppressionInterval
        return true
    }

    package mutating func observe(_ id: String, on screen: @autoclosure () -> String? = nil, at time: Double, suppressed: Bool,
                                  dragging: Bool, userInput: Bool) -> Bool {
        guard !dragging else { return false }
        let newWindow = admissionDeadlines.removeValue(forKey: id) != nil
        if userInput { pointerPress = nil }
        if !newWindow, let press = pointerPress, time < press.until, scopesPointerFocus, !press.allows(screen()) {
            // The activated app can still report its previous key window on another monitor.
            suppressedFocus = id
            return false
        }
        if let click = bodyClick, time < click.until, click.target != id, !newWindow, !userInput { return false }
        if newWindow || userInput { bodyClick = nil }
        if suppressed && !userInput && !newWindow {
            if (raisedUntil[id] ?? 0) > time { suppressedFocus = id }
            return false
        }
        if suppressedFocus == id && !userInput && !newWindow { return false }
        suppressedFocus = nil
        guard focusedID != id else { return false }
        focusedID = id
        return true
    }

    package mutating func clicked(_ id: String) {
        admissionDeadlines.removeValue(forKey: id)
        suppressedFocus = nil
        focusedID = id
    }

    package enum ClickResult { case body, focused }

    package mutating func confirmClick(_ id: String, on screen: String?, bodyWindow: String?,
                                       nativeFocused: Bool, at time: Double) -> ClickResult? {
        guard bodyWindow == id || nativeFocused else { return nil }
        if let press = pointerPress, !press.allows(screen) {
            suppressedFocus = id
            return nil
        }
        clicked(id)
        guard bodyWindow == id else { return .focused }
        // The app can keep reporting its previous key window while the strip slides.
        // Allow a delayed native placement to settle; the activating raise shortens this window.
        bodyClick = (id, time, time + 1.5)
        return .body
    }

    package mutating func supersedeBodyClick(with id: String) {
        if bodyClick?.target != id {
            bodyClick = nil
            pointerPress = nil
        }
    }

    /// AX and NSWorkspace can report focus before AppKit delivers the click, even
    /// after a quick release. The timestamps are monotonic, sampled through two APIs.
    package static func awaitingMouseDown(at time: Double, handledThrough: Double, downAge: Double, keyAge: Double) -> Bool {
        downAge < suppressionInterval && downAge <= keyAge && time - downAge > handledThrough + 0.001
    }

    package mutating func beganClick() {
        pointerPress = nil
        bodyClick = nil
        // The macOS Dock can activate a window even though the press hits no managed AX element.
        if let suppressedFocus, suppressedFocus == focusedID { focusedID = nil }
        suppressedFocus = nil
        raisedUntil.removeAll()
    }

    package mutating func locatePress(at point: CGPoint, time: Double, displays: [String: CGRect],
                                     hit: (screen: String, clipped: Bool)?) {
        guard let screen = Workspace.physicalScreen(at: point, in: displays), let bounds = displays[screen] else { return }
        // Include the native resize border and the full exposed part of a clipped strip column.
        let nearEdge = min(point.x - bounds.minX, bounds.maxX - point.x) <= 10 ||
            hit.map { $0.clipped || $0.screen != screen } == true
        pointerPress = PointerPress(screen: screen, at: time, nearEdge: nearEdge, until: time + Self.suppressionInterval)
    }

    package mutating func releasedPointer(on screen: String?, at time: Double) {
        pointerPress?.releaseScreen = screen
        pointerPress?.until = time + Self.suppressionInterval
    }

    package mutating func forget(_ id: String) {
        if bodyClick?.target == id { bodyClick = nil }
        if focusedID == id { focusedID = nil }
        if suppressedFocus == id { suppressedFocus = nil }
        admissionDeadlines.removeValue(forKey: id)
        raisedUntil.removeValue(forKey: id)
    }
}
